import base64
import io
import os
from typing import Any, Dict, Optional

import boto3


class StructuredDocumentExtractionError(ValueError):
    pass


def _to_bytes(document: Any) -> bytes:
    if document is None:
        raise StructuredDocumentExtractionError("document is required")

    if isinstance(document, bytes):
        return document

    if isinstance(document, str):
        if os.path.exists(document):
            with open(document, "rb") as f:
                return f.read()
        try:
            return base64.b64decode(document, validate=True)
        except Exception as exc:
            raise StructuredDocumentExtractionError(
                "document must be a file path, raw bytes, or base64-encoded string"
            ) from exc

    if hasattr(document, "read"):
        data = document.read()
        if isinstance(data, str):
            data = data.encode("utf-8")
        return data

    raise StructuredDocumentExtractionError(
        "document must be a file path, bytes, base64 string, or file-like object"
    )


def _best_value(field: Any) -> Optional[Any]:
    if field is None:
        return None
    if isinstance(field, dict):
        if "ValueDetection" in field and isinstance(field["ValueDetection"], dict):
            return field["ValueDetection"].get("Text")
        return field.get("Value")
    return getattr(field, "Text", None) or getattr(field, "Value", None)


def _best_confidence(field: Any) -> Optional[float]:
    if field is None:
        return None
    if isinstance(field, dict):
        if "ValueDetection" in field and isinstance(field["ValueDetection"], dict):
            return field["ValueDetection"].get("Confidence")
        return field.get("Confidence")
    return getattr(field, "Confidence", None)


def _normalize_field(name: str, value: Any, confidence: Any) -> Dict[str, Any]:
    return {"name": name, "value": value, "confidence": confidence}


def extract_and_validate_structured_fields(
    document: Any,
    required_fields: Dict[str, float],
    *,
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Validate required structured fields and confidence scores using Amazon Textract AnalyzeExpense.

    Args:
        document: File path, bytes, base64 string, or file-like object.
        required_fields: Mapping of required field names to minimum confidence thresholds.
            Example: {"InvoiceReceiptId": 90.0, "Total": 85.0}
        region_name: Optional AWS region name.

    Returns:
        Dict with:
            - fields: normalized extracted fields
            - validated: boolean
            - missing_fields: list[str]
            - low_confidence_fields: list[dict]
            - raw_response: Textract response

    Raises:
        StructuredDocumentExtractionError: on missing/invalid fields or confidence failures.
    """
    if not isinstance(required_fields, dict) or not required_fields:
        raise StructuredDocumentExtractionError("required_fields must be a non-empty dict")

    client_kwargs = {}
    if region_name:
        client_kwargs["region_name"] = region_name

    textract = boto3.client("textract", **client_kwargs)
    document_bytes = _to_bytes(document)

    response = textract.analyze_expense(Document={"Bytes": document_bytes})

    expense_docs = response.get("ExpenseDocuments", []) if isinstance(response, dict) else []
    if not expense_docs:
        raise StructuredDocumentExtractionError("No ExpenseDocuments returned by Textract")

    extracted: Dict[str, Dict[str, Any]] = {}
    for expense_doc in expense_docs:
        for item in expense_doc.get("SummaryFields", []):
            field_type = item.get("Type", {}).get("Text")
            value = _best_value(item)
            confidence = _best_confidence(item)
            if field_type:
                extracted[field_type] = _normalize_field(field_type, value, confidence)

    missing_fields = []
    low_confidence_fields = []

    for field_name, min_confidence in required_fields.items():
        field = extracted.get(field_name)
        if field is None or field.get("value") in (None, ""):
            missing_fields.append(field_name)
            continue

        conf = field.get("confidence")
        if conf is None or float(conf) < float(min_confidence):
            low_confidence_fields.append(
                {
                    "name": field_name,
                    "confidence": conf,
                    "minimum_confidence": float(min_confidence),
                    "value": field.get("value"),
                }
            )

    validated = not missing_fields and not low_confidence_fields
    if not validated:
        parts = []
        if missing_fields:
            parts.append(f"missing_fields={missing_fields}")
        if low_confidence_fields:
            parts.append(f"low_confidence_fields={low_confidence_fields}")
        raise StructuredDocumentExtractionError("; ".join(parts))

    return {
        "fields": extracted,
        "validated": True,
        "missing_fields": [],
        "low_confidence_fields": [],
        "raw_response": response,
    }
